                \coordinate (O) at (0,0);
                \draw[->,very thick,BrandBlue] (O) -- (2.6,0) node[right] {$x$};
                \draw[->,very thick,BrandGreen] (O) -- (-1.0,-0.9) node[left] {$y$};
                \draw[->,very thick,BrandYellow!80!black] (O) -- (0,2.4) node[above] {$z$};
                \draw[->,thick,gray] (0.7,0) arc[start angle=0,end angle=55,radius=0.7];
                \draw[->,thick,gray] (-0.25,0.9) arc[start angle=125,end angle=45,radius=0.8];
