\begin{tikzpicture}[
        node distance=0.75cm,
        >=Latex,
        box/.style={draw,rounded corners,thick,minimum width=2.6cm,minimum height=0.85cm,align=center,font=\scriptsize}
    ]
        \node[box,draw=BrandBlue,fill=IdeaBody] (p) {$\boldsymbol{p}$\\vector inicial};
        \node[box,draw=BrandGreen,fill=PracticeBody,right=of p] (r1) {$R_1$\\primera rotación};
        \node[box,draw=BrandBlue,fill=IdeaBody,right=of r1] (p1) {$\boldsymbol{p}_1$\\resultado intermedio};
        \node[box,draw=BrandGreen,fill=PracticeBody,right=of p1] (r2) {$R_2$\\segunda rotación};
        \node[box,draw=BrandYellow!80!black,fill=BrandYellow!15,right=of r2] (p2) {$\boldsymbol{p}_2$\\resultado final};

        \draw[->,thick] (p) -- (r1);
        \draw[->,thick] (r1) -- (p1);
        \draw[->,thick] (p1) -- (r2);
        \draw[->,thick] (r2) -- (p2);
    \end{tikzpicture}

\begin{tikzpicture}[scale=0.65,>=Latex,every node/.style={font=\scriptsize}]
        \coordinate (O) at (0,0);
        \draw[->,thick] (O) -- (3.0,0) node[right] {$x$};
        \draw[->,thick] (O) -- (-1.2,-1.0) node[left] {$y$};
        \draw[->,thick] (O) -- (0,2.5) node[above] {$z$};
        \draw[->,very thick,BrandBlue] (O) -- (0,2.0) node[above left] {$\boldsymbol p$};
        \draw[->,very thick,BrandGreen] (O) -- (2.3,0) node[below right] {$\boldsymbol p_B$};
        \draw[->,very thick,BrandYellow!80!black] (O) -- (1.0,0.85) node[above right] {$\boldsymbol{p_A}$};
        \node[align=center] at (1.0,-1.45) {Secuencias distintas\\producen direcciones distintas};
    \end{tikzpicture}

\begin{tikzpicture}[scale=0.9,>=Latex,every node/.style={font=\scriptsize}]
        \node[draw,rounded corners,thick,fill=IdeaBody,minimum width=2.4cm,minimum height=0.75cm] (p) {$\boldsymbol p$};
        \node[draw,rounded corners,thick,fill=PracticeBody,right=0.6cm of p,minimum width=2.4cm,minimum height=0.75cm] (rx) {$R_x(\alpha)$};
        \node[draw,rounded corners,thick,fill=IdeaBody,right=0.6cm of rx,minimum width=2.4cm,minimum height=0.75cm] (p1) {$\boldsymbol p_1$};
        \node[draw,rounded corners,thick,fill=PracticeBody,right=0.6cm of p1,minimum width=2.4cm,minimum height=0.75cm] (ry) {$R_y(\beta)$};
        \node[draw,rounded corners,thick,fill=BrandYellow!15,draw=BrandYellow!80!black,right=0.6cm of ry,minimum width=2.4cm,minimum height=0.75cm] (pf) {$\boldsymbol p'$};
        \draw[->,thick] (p) -- (rx);
        \draw[->,thick] (rx) -- (p1);
        \draw[->,thick] (p1) -- (ry);
        \draw[->,thick] (ry) -- (pf);
    \end{tikzpicture}

\begin{tikzpicture}[
    scale=0.95,
    >=Latex,
    every node/.style={font=\scriptsize}
    ]




    \coordinate (O) at (0,0);


    \draw[->,very thick,BrandBlue]
    (O) -- (3.0,0)
    node[right] {$x_0$};

    \draw[->,very thick,BrandGreen]
    (O) -- (-1.1,-1.0)
    node[left] {$y_0$};

    \draw[->,very thick,BrandYellow!80!black]
    (O) -- (0,2.6)
    node[above] {$z_0$};

    \node[below right] at (O) {$\{0\}$};


    \draw[->,very thick,gray]
    (3.3,1.2) -- (4.3,1.2);

    \node[gray,above]
    at (3.8,1.2)
    {$R_{z_0}(\theta)$};




    \begin{scope}[shift={(6.0,0)}]

        \coordinate (P) at (0,0);




        \draw[->,thick,BrandBlue!45]
        (P) -- (3.0,0)
        node[right] {$x_0$};

        \draw[->,thick,BrandGreen!45]
        (P) -- (-1.1,-1.0)
        node[left] {$y_0$};

        \draw[->,thick,BrandYellow!55!black]
        (P) -- (0,2.6)
        node[above] {$z_0$};





        \begin{scope}[rotate=40]

            \draw[->,very thick,BrandBlue]
            (P) -- (2.7,0)
            node[right] {$x_1$};

            \draw[->,very thick,BrandGreen]
            (P) -- (-1.0,-0.9)
            node[left] {$y_1$};

        \end{scope}


        \draw[->,very thick,BrandYellow!80!black]
        (P) -- (0,2.6);

        \node[right,BrandYellow!80!black]
        at (0.08,2.15)
        {$z_1=z_0$};


        \draw[->,thick,gray]
        (0.8,0)
        arc[
        start angle=0,
        end angle=40,
        radius=0.8
        ];

        \node[gray]
        at (1.02,0.32)
        {$\theta$};

        \node[below right]
        at (P)
        {$\{1\}$};

    \end{scope}

\end{tikzpicture}

\begin{tikzpicture}[
            scale=0.88,
            >=Latex,
            every node/.style={font=\scriptsize}
            ]




            \coordinate (O0) at (0,0);

            \draw[->,very thick,BrandBlue]
            (O0) -- (2.4,0)
            node[right] {$x_0$};

            \draw[->,very thick,BrandGreen]
            (O0) -- (-0.9,-0.8)
            node[left] {$y_0$};

            \draw[->,very thick,BrandYellow!80!black]
            (O0) -- (0,2.2)
            node[above] {$z_0$};

            \node[below right] at (O0) {$\{0\}$};




            \draw[->,very thick,gray]
            (2.8,1.25) -- (3.8,1.25);

            \node[gray,above] at (3.3,1.25)
            {$R_{z_0}(\alpha)$};






            \coordinate (O1) at (5.2,0);


            \draw[->,very thick,BrandBlue]
            (O1) -- ++(2.15,1.05)
            node[right] {$x_1$};


            \draw[->,very thick,BrandGreen]
            (O1) -- ++(0.45,-1.15)
            node[below] {$y_1$};


            \draw[->,very thick,BrandYellow!80!black]
            (O1) -- ++(0,2.2)
            node[above] {$z_1=z_0$};

            \node[below right] at (O1) {$\{1\}$};


            \draw[->,thick,gray]
            ($(O1)+(0.75,0)$)
            arc[start angle=0,end angle=26,radius=0.75];

            \node[gray] at ($(O1)+(0.95,0.25)$) {$\alpha$};





            \draw[->,very thick,gray]
            (7.9,1.25) -- (8.9,1.25);

            \node[gray,above] at (8.4,1.25)
            {$R_{x_1}(\beta)$};






            \coordinate (O2) at (10.3,0);




            \draw[->,thick,dashed,BrandBlue!45]
            (O2) -- ++(2.15,1.05)
            node[right] {$x_1$};

            \draw[->,thick,dashed,BrandGreen!45]
            (O2) -- ++(-0.45,-1.15)
            node[left] {$y_1$};

            \draw[->,thick,dashed,BrandYellow!50!black]
            (O2) -- ++(0,2.2)
            node[above] {$z_1$};




            \draw[->,very thick,BrandBlue]
            (O2) -- ++(2.15,1.05)
            node[above right] {$x_2=x_1$};





            \draw[->,very thick,BrandGreen]
            (O2) -- ++(0.10,-1.30)
            node[below] {$y_2$};

            \draw[->,very thick,BrandYellow!80!black]
            (O2) -- ++(-0.75,1.95)
            node[above left] {$z_2$};

            \node[below right] at (O2) {$\{2\}$};


            \draw[->,thick,gray]
            ($(O2)+(0.55,0.28)$)
            arc[start angle=25,end angle=105,
            x radius=0.52,y radius=0.30];

            \node[gray] at ($(O2)+(0.35,0.78)$) {$\beta$};

        \end{tikzpicture}
